			pu.group.position.y = 1.5 + Math.sin(pu.bobPhase) * 0.5;
			pu.group.rotation.y += delta * 2;

			// Fade when expiring
			if (pu.lifetime < 3) {
				const children = pu.group.children as Mesh[];
				for (const ch of children) {
					if (ch.material && 'opacity' in ch.material) {
